import pandas as pd
import ast
import math

df_ts = pd.read_csv('/app/dataset/timesheet.csv')
df_emp = pd.read_csv('/app/dataset/employees.csv')
df_tasks = pd.read_csv('/app/dataset/tasks.csv')

mapping = {
    62020111425: 65020111422,
    68011910138: 68011810139,
    16102016795: 96102016751,
    84731091580: 87031491580,
    15720759071: 75020759171
}
df_ts['employee_id_clean'] = df_ts['employee_id'].replace(mapping)

def clean_date(d):
    if d == '2025-04-31':
        return '2025-04-30'
    elif d == '2025-06-31':
        return '2025-06-30'
    return d

df_ts['date_clean'] = df_ts['date'].apply(clean_date)

def get_billing_month_tuesday(d):
    if '2025-03-04' <= d <= '2025-03-31':
        return 3
    elif '2025-04-01' <= d <= '2025-05-05':
        return 4
    elif '2025-05-06' <= d <= '2025-06-02':
        return 5
    elif '2025-06-03' <= d <= '2025-06-30':
        return 6
    return None

def get_billing_month_calendar(d):
    # just parse the month part
    return int(d.split('-')[1])

emp_rates = df_emp.set_index('PESEL')['hourly_rate'].to_dict()
task_pay = df_tasks.set_index('task_id')['pay_per_completion'].to_dict()

# Calculate Approach A (calculated bonus) under both partitionings
salaries_tuesday = {}
salaries_calendar = {}

def std_round(val):
    return math.floor(val + 0.5)

# Clean timesheet (exclude hours == 0 and negative bonus)
df_ts_clean = df_ts[(df_ts['hours_worked'] > 0) & (df_ts['bonus'] >= 0)].copy()

for pesel in sorted(emp_rates.keys()):
    pesel_str = str(pesel).zfill(11)
    salaries_tuesday[pesel_str] = []
    salaries_calendar[pesel_str] = []

    emp_df = df_ts_clean[df_ts_clean['employee_id_clean'] == pesel].copy()

    # Tuesday partitioning
    emp_df['m_tues'] = emp_df['date_clean'].apply(get_billing_month_tuesday)
    for month in [3, 4, 5, 6]:
        m_df = emp_df[emp_df['m_tues'] == month]
        hours = m_df['hours_worked'].sum()
        base = hours * emp_rates[pesel]
        bonus = 0
        for idx, row in m_df.iterrows():
            try:
                tasks = ast.literal_eval(row['performed_tasks'])
            except:
                tasks = []
            bonus += sum(task_pay.get(tid, 0) for tid in tasks)
        salaries_tuesday[pesel_str].append(std_round(base + bonus))

    # Calendar partitioning
    emp_df['m_cal'] = emp_df['date_clean'].apply(get_billing_month_calendar)
    for month in [3, 4, 5, 6]:
        m_df = emp_df[emp_df['m_cal'] == month]
        hours = m_df['hours_worked'].sum()
        base = hours * emp_rates[pesel]
        bonus = 0
        for idx, row in m_df.iterrows():
            try:
                tasks = ast.literal_eval(row['performed_tasks'])
            except:
                tasks = []
            bonus += sum(task_pay.get(tid, 0) for tid in tasks)
        salaries_calendar[pesel_str].append(std_round(base + bonus))

diff_count = 0
for pesel_str in salaries_tuesday:
    if salaries_tuesday[pesel_str] != salaries_calendar[pesel_str]:
        diff_count += 1
        if diff_count <= 5:
            print(f'Employee {pesel_str} diff:')
            print(f'  Tuesday:  {salaries_tuesday[pesel_str]}')
            print(f'  Calendar: {salaries_calendar[pesel_str]}')

print(f'Total employees with differences between Tuesday and Calendar boundaries: {diff_count} out of 22')
"
